    )
    case split(id: UInt32, horizontal: Bool
    )
    case resizePane(id: UInt32, columns: UInt16, rows: UInt16
    )
    case zoomPane(id: UInt32
    )
    case closePane(id: UInt32
    )
    case resize(columns: UInt16, rows: UInt16
    )
